import os, re, glob
import pytesseract
from PIL import Image
import openpyxl

IMG_DIR = '/app/workspace/dataset/img'
OUT = '/app/workspace/stat_ocr.xlsx'

EXCLUDE = ['SUBTOTAL','SUB TOTAL','SUB-TOTAL','TAX','GST','SST','DISCOUNT','CHANGE','CASH TENDERED']

# Priority lists of keywords
PRIORITY = [
    ['GRAND TOTAL'],
    ['TOTAL RM','TOTAL: RM'],
    ['TOTAL AMOUNT'],
    ['TOTAL DUE','AMOUNT DUE','BALANCE DUE','NETT TOTAL','NET TOTAL','TOTAL','AMOUNT'],
]

NUM_RE = re.compile(r'(\d{1,3}(?:,\d{3})*\.\d{2}|\d+\.\d{2})')

def extract_amount_from_line(line):
    nums = NUM_RE.findall(line)
    if nums:
        return nums[-1].replace(',', '')
    return None

def find_total(text):
    lines = text.split('\n')
    upper = [l.upper() for l in lines]
    for kwlist in PRIORITY:
        for i, ul in enumerate(upper):
            if any(ex in ul for ex in EXCLUDE):
                continue
            for kw in kwlist:
                if kw in ul:
                    # try this line
                    amt = extract_amount_from_line(lines[i])
                    if amt:
                        return amt
                    # fallback: next non-empty line, take last number
                    for j in range(i+1, min(i+4, len(lines))):
                        if lines[j].strip():
                            amt2 = extract_amount_from_line(lines[j])
                            if amt2:
                                return amt2
                            break
    return None

MONTHS = {'JAN':1,'FEB':2,'MAR':3,'APR':4,'MAY':5,'JUN':6,'JUL':7,'AUG':8,'SEP':9,'SEPT':9,'OCT':10,'NOV':11,'DEC':12}

def norm_date(d, m, y):
    try:
        d = int(d); m = int(m); y = int(y)
        if y < 100:
            y += 2000
        if 1 <= m <= 12 and 1 <= d <= 31 and 2000 <= y <= 2099:
            return f'{y:04d}-{m:02d}-{d:02d}'
    except:
        pass
    return None

def find_date(text):
    # DD-MM-YYYY or DD/MM/YYYY  or DD.MM.YYYY
    for m in re.finditer(r'(\d{1,2})[-/.](\d{1,2})[-/.](\d{2,4})', text):
        d, mo, y = m.group(1), m.group(2), m.group(3)
        r = norm_date(d, mo, y)
        if r: return r
    # YYYY-MM-DD
    for m in re.finditer(r'(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})', text):
        y, mo, d = m.group(1), m.group(2), m.group(3)
        r = norm_date(d, mo, y)
        if r: return r
    # DD MMM YYYY
    for m in re.finditer(r'(\d{1,2})[\s-]+([A-Za-z]{3,4})[\s-]+(\d{2,4})', text):
        d = m.group(1); mo_s = m.group(2).upper(); y = m.group(3)
        if mo_s in MONTHS:
            r = norm_date(d, MONTHS[mo_s], y)
            if r: return r
    return None

files = sorted(os.listdir(IMG_DIR))
results = []
for fn in files:
    path = os.path.join(IMG_DIR, fn)
    try:
        text = pytesseract.image_to_string(Image.open(path))
    except Exception as e:
        text = ''
    date = find_date(text)
    total = find_total(text)
    print(fn, '|', date, '|', total)
    results.append((fn, date, total))

wb = openpyxl.Workbook()
