# excludes that don't conflict with TOTAL keyword
HARD_EXCLUDE = ['SUBTOTAL','SUB TOTAL','SUB-TOTAL','DISCOUNT','CHANGE','CASH TENDERED']
# excludes only if line doesn't contain a TOTAL/AMOUNT keyword
SOFT_EXCLUDE = ['TAX','GST','SST']

PRIORITY = [
    ['GRAND TOTAL'],
    ['TOTAL RM','TOTAL: RM'],
    ['TOTAL AMOUNT'],
    ['TOTAL DUE','AMOUNT DUE','BALANCE DUE','NETT TOTAL','NET TOTAL','TOTAL','AMOUNT'],
]

NUM_RE = re.compile(r'(\d{1,3}(?:,\d{3})*\.\d{2}|\d+\.\d{2})')
NUM_LOOSE = re.compile(r'(\d+[.,]\d{2})')

def extract_amount(line, loose=False):
    nums = NUM_RE.findall(line)
    if nums:
        return nums[-1].replace(',', '')
    if loose:
        nums = NUM_LOOSE.findall(line)
        if nums:
            v = nums[-1]
            # if comma is decimal
            if v.count(',')==1 and '.' not in v:
                v = v.replace(',', '.')
            return v
    return None

def line_has_total_kw(ul):
    return any(k in ul for k in ['TOTAL','AMOUNT','BALANCE'])

def is_excluded(ul):
    if any(ex in ul for ex in HARD_EXCLUDE):
        return True
    if any(ex in ul for ex in SOFT_EXCLUDE):
        # only exclude if no total keyword
        if not line_has_total_kw(ul.replace('SUBTOTAL','').replace('SUB TOTAL','')):
            return True
        # if it has TOTAL but also TAX/GST, allow only if 'TOTAL' is the main word, not 'TOTAL TAX' etc.
        # Heuristic: 'TOTAL' present and line longer
        # Actually allow it (don't exclude)
        return False
    return False

def find_total(text):
    lines = text.split('\n')
    upper = [l.upper() for l in lines]
    for kwlist in PRIORITY:
        for i, ul in enumerate(upper):
            if is_excluded(ul):
                continue
            for kw in kwlist:
                if kw in ul:
                    amt = extract_amount(lines[i])
                    if amt:
                        return amt
                    # try loose
                    amt = extract_amount(lines[i], loose=True)
                    if amt:
                        return amt
                    # fallback: next non-empty line, take last number
                    for j in range(i+1, min(i+4, len(lines))):
                        if lines[j].strip():
                            amt2 = extract_amount(lines[j])
                            if amt2:
                                return amt2
                            amt2 = extract_amount(lines[j], loose=True)
                            if amt2:
                                return amt2
                            break
    return None

MONTHS = {'JAN':1,'FEB':2,'MAR':3,'APR':4,'MAY':5,'JUN':6,'JUL':7,'AUG':8,'SEP':9,'SEPT':9,'OCT':10,'NOV':11,'DEC':12}

def norm_date(d, m, y):
    try:
        d = int(d); m = int(m); y = int(y)
        if y < 100:
            y += 2000
        if 1 <= m <= 12 and 1 <= d <= 31 and 2000 <= y <= 2099:
            return f'{y:04d}-{m:02d}-{d:02d}'
    except:
        pass
    return None

def find_date(text):
    for m in re.finditer(r'(\d{1,2})[-/.](\d{1,2})[-/.](\d{2,4})', text):
        r = norm_date(m.group(1), m.group(2), m.group(3))
        if r: return r
    for m in re.finditer(r'(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})', text):
        r = norm_date(m.group(3), m.group(2), m.group(1))
        if r: return r
    for m in re.finditer(r'(\d{1,2})[\s-]+([A-Za-z]{3,4})[\s-]+(\d{2,4})', text):
        mo_s = m.group(2).upper()
        if mo_s in MONTHS:
            r = norm_date(m.group(1), MONTHS[mo_s], m.group(3))
            if r: return r
    # DDMMYYYY no separator 8 digits
    for m in re.finditer(r'\b(\d{2})(\d{2})(\d{4})\b', text):
        r = norm_date(m.group(1), m.group(2), m.group(3))
        if r: return r
    return None

def ocr(path):
    return pytesseract.image_to_string(Image.open(path))

files = sorted(os.listdir(IMG_DIR))
results = []
for fn in files:
    path = os.path.join(IMG_DIR, fn)
    try:
        text = ocr(path)
    except Exception as e:
        text = ''
    date = find_date(text)
    total = find_total(text)
    print(fn, '|', date, '|', total)
    results.append((fn, date, total))

wb = openpyxl.Workbook()
ws = wb.active
ws.title = 'results'
ws.append(['filename','date','total_amount'])
for r in results:
    ws.append([r[0], r[1] if r[1] else None, r[2] if r[2] else None])
wb.save(OUT)
print('saved', OUT)
